-- Explicit SchoolPro fee exception types and value modes. Finance editing remains restricted to proprietor, administrator, accountant and bursar by RLS.
alter table public.schoolpro_fee_exceptions add column if not exists exception_type text not null default 'fixed_discount', add column if not exists value_type text not null default 'fixed', add column if not exists value numeric not null default 0, add column if not exists partial_waiver numeric not null default 0;
alter table public.schoolpro_fee_exceptions drop constraint if exists schoolpro_fee_exceptions_exception_type_check; alter table public.schoolpro_fee_exceptions add constraint schoolpro_fee_exceptions_exception_type_check check(exception_type in ('scholarship','discount','partial_waiver','full_waiver'));
alter table public.schoolpro_fee_exceptions drop constraint if exists schoolpro_fee_exceptions_value_type_check; alter table public.schoolpro_fee_exceptions add constraint schoolpro_fee_exceptions_value_type_check check(value_type in ('fixed','percentage'));
alter table public.schoolpro_fee_exceptions drop constraint if exists schoolpro_fee_exceptions_value_check; alter table public.schoolpro_fee_exceptions add constraint schoolpro_fee_exceptions_value_check check(value>=0 and (value_type<>'percentage' or value<=100));
-- generate_schoolpro_class_invoices was updated live to translate fixed/percentage scholarship, discount and partial/full waiver into audited invoice amounts, while retaining the finance-role authorization check.
